def load_summary(events: Sequence[trail.Event]) -> str:
    """実行の要約の1行。"""
    return f"{_outcome(events)}（人の決定 {trail.count(events, trail.DECIDED)} 回）"

def padded(items: list[str], size: int) -> list[str]:
    """一覧を size 件にそろえる。"""
    while len(items) < size:
        items.append(MISSING)
    return items

def is_reviewed(ctx: context.Context) -> bool:
    """結果のファイルがあれば、このラウンドのレビューは済んだとみなす。"""
    return ctx.where.result_path(ctx.run_id, ctx.next.number).is_file()

def lens_note(lens: str) -> str:
    """探索役に渡す観点の説明。"""
    return f"あなたは探索役です。{lens} の観点だけで差分を読み、指摘を JSON で書いてください。"

def stat_rows(found: Sequence[changes.Stat]) -> str:
    """変えたファイルの表。"""
    lines = ["| ファイル | 足した行 | 消した行 |", "|---|---|---|"]
    lines += [f"| {stat.path} | {stat.added} | {stat.deleted} |" for stat in found]
    return "\n".join(lines)

def is_lower_tier(left: str, right: str) -> bool:
    """left の段が right の段より低いか。"""
    return tier_order(left) < tier_order(right)

class SourceJiraTest(unittest.TestCase):
    def test_source_jira(self) -> None:
        where = support.make_repo(self)
        origin = trail.Origin("jira", "", "", "題名")
        with self.assertRaisesRegex(StageError, "--ref"):
            intake.start(where, origin, support.body_file(where), support.NOW)
